  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [240+Math.sin(t*0.3)*120,120+Math.cos(t*0.2)*70,0.06,2.0,0],
    [240+Math.cos(t*0.25)*140,120+Math.sin(t*0.35)*80,0.05,2.3,1],
    [120+Math.cos(t*0.4+1)*80,180+Math.sin(t*0.3+2)*60,0.08,1.7,0.5],
    [360+Math.sin(t*0.35+3)*90,60+Math.cos(t*0.45+1)*70,0.07,2.1,1.5],
    [160+Math.sin(t*0.5+2)*100,80+Math.cos(t*0.4+3)*50,0.09,1.5,2],
    [320+Math.cos(t*0.45+4)*110,160+Math.sin(t*0.55+2)*60,0.065,1.9,0.8],
    [200+Math.sin(t*0.2+5)*60,200+Math.cos(t*0.3+4)*40,0.11,2.5,1.2],
    [280+Math.cos(t*0.38+6)*70,40+Math.sin(t*0.42+5)*50,0.075,2.2,2.5]
  ];
  let act=0,inh=0,mod=0;
  for(const[sX,sY,f,sp,ph]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    act+=Math.sin(d*f-t*sp+ph);
    inh+=Math.sin(d*f*0.7+t*sp*0.6+ph+1.5);
    mod+=Math.sin(d*f*1.3-t*sp*0.8+ph+3)*0.5;
  }
  act/=8;inh/=8;mod/=8;
  const bg1=(Math.sin(sx*0.035+sy*0.022+t*0.7)+Math.sin(sx*0.028-sy*0.038+t))/2;
  const bg2=(Math.sin(sx*0.08+sy*0.06-t*1.5)+Math.sin(sx*0.06-sy*0.09+t*1.8))*0.3;
  const bg3=Math.sin(sx*0.15+sy*0.12+t*2.5)*0.15;
  const bg=bg1+bg2+bg3;
