  const cell=Math.tanh((cellX+cellY+Math.sin((sx+sy)*0.08+t)*0.4)*1.8)*0.25;
  const r1=Math.tanh((act-inh*0.65+bg*0.25+spiral)*2);
  const r2=Math.tanh((act*0.8-inh+mod+spiral*0.7+bg*0.2)*1.8);
  const combined=r1*0.6+r2*0.4;
  const blend=combined*0.7+cell*0.2+spiral*0.1;
  const v=Math.tanh(blend*1.5)*0.5+0.5;
  const pal=[[5,12,52],[10,45,85],[15,90,120],[25,140,130],[60,175,110],[140,195,80],[210,190,60],[230,145,55],[215,90,55],[180,55,65],[120,30,70],[60,18,55],[20,12,48],[5,12,52]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i,sf=f*f*(3-2*f);
  const pr=pal[i][0]+(pal[i+1][0]-pal[i][0])*sf;
  const pg=pal[i][1]+(pal[i+1][1]-pal[i][1])*sf;
  const pb=pal[i][2]+(pal[i+1][2]-pal[i][2])*sf;
  const lum=0.85+Math.sin(combined*Math.PI)*0.15;
  const bright=Math.abs(combined)>0.65?1.12:1.0;
  const vig=1-Math.pow(dist/280,2)*0.15;
  return[Math.min(255,Math.max(0,pr*lum*bright*vig))|0,Math.min(255,Math.max(0,pg*lum*bright*vig))|0,Math.min(255,Math.max(0,pb*lum*bright*vig))|0];
